1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Hash8;
8	import org.springframework.samples.petclinic.model.Locality;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	
12	/**
13	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>}: REGION is
14	 * the region code derived from the owner's postcode (see {@link Locality#regionOf}) and
15	 * HASH8 is the owner's identity hash (see {@link Hash8}), e.g. {@code NSW-1A2B3C4D}. When
16	 * the computed code collides with an existing owner's
17	 * {@code customerCode}, {@code -<n>} is appended with the smallest {@code n} of 2 or more
18	 * that makes it unique. Runs after {@link BuildOwner} (so the telephone is already
19	 * normalized) and before {@link SaveOwner}.
20	 */
21	public class AssignCustomerCode {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
24	        String region = Locality.regionOf(owner.getPostcode());
25	        String base = region + "-" + Hash8.of(owner);
26	        owner.setCustomerCode(deduplicate(base, existingCodes(ownerRepository)));
27	    }
28	
29	    private static Set<String> existingCodes(OwnerRepository ownerRepository) {
30	        Set<String> codes = new HashSet<>();
31	        for (Owner existing : ownerRepository.findAll()) {
32	            String code = existing.getCustomerCode();
33	            if (code != null) {
34	                codes.add(code);
35	            }
36	        }
37	        return codes;
38	    }
39	
40	    /** Returns {@code base}, or {@code base-<n>} with the smallest {@code n >= 2} not in {@code taken}. */
41	    private static String deduplicate(String base, Set<String> taken) {
42	        if (!taken.contains(base)) {
43	            return base;
44	        }
45	        for (int n = 2; ; n++) {
46	            String candidate = base + "-" + n;
47	            if (!taken.contains(candidate)) {
48	                return candidate;
49	            }
50	        }
51	    }
52	}
