3	/**
4	 * Derives an owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'}
5	 * where YY is the two-digit {@link FiscalYear} derived from the owner's
6	 * (business-day-adjusted) registrationDate (e.g. {@code 'NSW-1A2B3C4D-M26'}).
7	 *
8	 * <p>This is the one place the membership number is assembled, so the owner response and
9	 * the creation audit trail read the same value rather than each rebuilding it. Null when
10	 * the owner has no customerCode or no registrationDate.
11	 */
12	public final class MembershipNumber {
13	
14	    private MembershipNumber() {
15	    }
16	
17	    /** The membership number for the given owner, or null when it cannot be derived. */
18	    public static String of(Owner owner) {
19	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
20	            return null;
21	        }
22	        return owner.getCustomerCode() + "-M" + FiscalYear.shortYear(owner.getRegistrationDate());
23	    }
24	}
