1	package org.springframework.samples.petclinic.model;
2	
3	/**
4	 * Derives the HASH8 segment of an owner's region-and-hash identity: the first 8 upper-case
5	 * hexadecimal characters of the {@link Sha256} digest over the concatenation of the owner's
6	 * normalized (E.164) telephone and lastName (e.g. {@code 1A2B3C4D}).
7	 *
8	 * <p>This is the one place the segment is computed, so every identity that embeds it (the
9	 * owner's {@code customerCode} today) reads the same value rather than re-deriving it. A
10	 * null telephone or lastName contributes an empty string to the concatenation.
11	 */
12	public final class Hash8 {
13	
14	    private Hash8() {
15	    }
16	
17	    /** The 8-character upper-case hex HASH8 segment for the given owner. */
18	    public static String of(Owner owner) {
19	        String source = nullToEmpty(owner.getTelephone()) + nullToEmpty(owner.getLastName());
20	        return Sha256.hex(source).substring(0, 8).toUpperCase();
21	    }
22	
23	    private static String nullToEmpty(String value) {
24	        return value == null ? "" : value;
25	    }
26	}
