     1	package org.springframework.samples.petclinic.model;
     2	
     3	/**
     4	 * Derives an owner's marketing segment, formatted {@code <TIER>_<AREA>}: one of
     5	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
     6	 * {@code STANDARD_REGIONAL}.
     7	 *
     8	 * <p>TIER is {@code PREMIUM} when the owner's {@link MembershipLevel} is 3 or more,
     9	 * otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's {@link Locality} is a
    10	 * known region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
    11	 */
    12	public final class OwnerSegment {
    13	
    14	    private OwnerSegment() {
    15	    }
    16	
    17	    /** The owner's marketing segment, formatted {@code <TIER>_<AREA>}. */
    18	    public static String of(Owner owner) {
    19	        String tier = MembershipLevel.of(owner) >= 3 ? "PREMIUM" : "STANDARD";
    20	        String area = Locality.UNKNOWN.equals(Locality.of(owner)) ? "REGIONAL" : "METRO";
    21	        return tier + "_" + area;
    22	    }
    23	}
