     1	package org.springframework.samples.petclinic.model;
     2	
     3	/**
     4	 * Computes a single Luhn check digit (0-9) over the digits contained in a string — the one
     5	 * place the algorithm lives, so the several places that pin a Luhn digit onto an identifier
     6	 * (such as an owner's {@link CheckDigit}) delegate here rather than re-implementing it.
     7	 *
     8	 * <p>The digits are processed right-to-left, doubling every second digit starting with the
     9	 * rightmost (subtracting 9 when a doubled digit exceeds 9); the check digit is the amount
    10	 * needed to bring the running total to the next multiple of ten. Non-digit characters are
    11	 * ignored.
    12	 */
    13	public final class Luhn {
    14	
    15	    private Luhn() {
    16	    }
    17	
    18	    /** The Luhn check digit (0-9) over the digits contained in {@code source}. */
    19	    public static int digit(String source) {
    20	        int sum = 0;
    21	        boolean dbl = true;
    22	        for (int i = source.length() - 1; i >= 0; i--) {
    23	            char c = source.charAt(i);
    24	            if (c < '0' || c > '9') {
    25	                continue;
    26	            }
    27	            int d = c - '0';
    28	            if (dbl) {
    29	                d *= 2;
    30	                if (d > 9) {
    31	                    d -= 9;
    32	                }
    33	            }
    34	            sum += d;
    35	            dbl = !dbl;
    36	        }
    37	        return (10 - (sum % 10)) % 10;
    38	    }
    39	}
