3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Derives an owner's fiscal year from their (business-day-adjusted) registrationDate.
8	 *
9	 * <p>The fiscal year starts on 1 July and is labelled by the calendar year in which it
10	 * ends: a date on or after 1 July falls in the fiscal year ending the following 30 June.
11	 * For example 1 July 2025 and 12 September 2025 both fall in fiscal year 2026, while 30
12	 * June 2025 falls in fiscal year 2025.
13	 *
14	 * <p>{@link #of(Owner)} formats this as {@code 'FY<YY>'} (the two-digit ending year, e.g.
15	 * {@code 'FY26'}); {@link #shortYear(LocalDate)} exposes the two-digit ending year on its
16	 * own and {@link #yearOf(LocalDate)} the four-digit ending year, for callers that build
17	 * their own segments (such as the membership number).
18	 */
19	public final class FiscalYear {
20	
21	    /** The month on whose first day the fiscal year begins. */
22	    private static final int START_MONTH = Month.JULY.getValue();
23	
24	    private FiscalYear() {
25	    }
26	
27	    /** The fiscal year label ({@code 'FY<YY>'}) for the owner, or null when unregistered. */
28	    public static String of(Owner owner) {
29	        LocalDate registrationDate = owner.getRegistrationDate();
30	        if (registrationDate == null) {
31	            return null;
32	        }
33	        return "FY" + shortYear(registrationDate);
34	    }
35	
36	    /** The two-digit ending year ({@code 'YY'}) of the fiscal year that {@code date} falls in. */
37	    public static String shortYear(LocalDate date) {
38	        return String.format("%02d", yearOf(date) % 100);
39	    }
40	
41	    /** The fiscal year (the calendar year it ends in) that {@code date} falls in. */
42	    public static int yearOf(LocalDate date) {
43	        return date.getMonthValue() >= START_MONTH ? date.getYear() + 1 : date.getYear();
44	    }
45	}
