14	 * its {@code identityKey} equals an existing non-deleted owner's (see the create pipeline's
15	 * identity block). Because the telephone is part of the key, two owners sharing only a last
16	 * name and postcode are no longer a hard duplicate — they surface as a soft match instead.
17	 */
18	public final class IdentityKey {
19	
20	    private IdentityKey() {
21	    }
22	
23	    /** The identity key for the given owner. */
24	    public static String of(Owner owner) {
25	        String key = segment(owner.getTelephone()) + "|" + segment(owner.getEmail()) + "|"
26	                + Soundex.of(owner.getLastName());
27	        return Sha256.hex(key);
28	    }
29	
30	    private static String segment(String value) {
31	        return value == null ? "" : value;
32	    }
33	}
