   115	     * Postcode is optional. When present (non-blank) it must be a 4-digit value that is valid
   116	     * for the owner's city per the fixed region ranges (see
   117	     * {@link org.springframework.samples.petclinic.model.Postcode}); an out-of-range or
   118	     * malformed value is a 400 (adds a "postcode" error). A valid value is stored trimmed back
   119	     * on the request so later steps persist and return it. A city with no known region accepts
   120	     * any 4-digit postcode, keeping the create request backward-compatible when absent.
   121	     */
   122	    /**
   123	     * Registration date is optional (it defaults to the server's current date in
   124	     * {@link BuildOwner} when absent). When supplied it must not be later than the server's
   125	     * current date; a future value is a 400 (adds a "registrationDate" error).
   126	     */
   127	    private static void validateRegistrationDate(OwnerFieldsDto request, List<String> errors) {
   128	        LocalDate registrationDate = request.getRegistrationDate();
   129	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
   130	            errors.add("registrationDate");
   131	        }
   132	    }
   133	
   134	    private static void validatePostcode(OwnerFieldsDto request, List<String> errors) {
   135	        String postcode = request.getPostcode();
   136	        if (postcode == null || postcode.isBlank()) {
   137	            return;
   138	        }
   139	        String trimmed = postcode.trim();
   140	        if (org.springframework.samples.petclinic.model.Postcode.isValidForCity(trimmed, request.getCity())) {
   141	            request.setPostcode(trimmed);
   142	        }
   143	        else if (!errors.contains("postcode")) {
   144	            errors.add("postcode");
   145	        }
   146	    }
   147	}

