17	 * registrationDate, membershipLevel and membershipNumber; and</li>
18	 * <li>an immutable structured {@link OwnerCreatedEvent} rendered as JSON
19	 * ({@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}),
