34	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
35	                MembershipLevel.of(owner), MembershipNumber.of(owner));
36	
37	        audit.info(OwnerCreatedEvent.of(SEQ.incrementAndGet(), owner).toJson());
38	    }
