1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.MembershipLevel;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Immutable structured audit event emitted (as JSON) when an owner is created.
8	 *
9	 * <p>Besides the human-readable audit line, {@link AuditOwnerCreated} emits one of
10	 * these per successful create as
11	 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}.
12	 *
13	 * <p>The event carries the owner's <em>current primary identifier</em>. Today that is
14	 * the {@code customerCode}; the value is sourced in a single place
15	 * ({@link #primaryIdentifier(Owner)}), so when the customerCode is later unified into
16	 * the memberId, changing that one method makes the event carry the memberId instead —
17	 * the rest of the pipeline is untouched.
18	 *
19	 * <p>A record: once constructed the event cannot be mutated.
20	 */
21	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, int membershipLevel) {
22	
23	    /** The {@code event} discriminator carried by every owner-created event. */
24	    public static final String EVENT = "OWNER_CREATED";
25	
26	    /**
27	     * Builds the event for a freshly created owner, reading the current primary
28	     * identifier and derived membership level from it.
29	     */
30	    public static OwnerCreatedEvent of(long seq, Owner owner) {
31	        return new OwnerCreatedEvent(seq, owner.getId(), primaryIdentifier(owner),
32	                MembershipLevel.of(owner));
33	    }
34	
35	    /**
36	     * The owner's current primary identifier. Today the {@code customerCode}; when the
37	     * customerCode is unified into the memberId, return {@code owner.getMemberId()} here
38	     * and the emitted event carries the memberId instead.
39	     */
40	    private static String primaryIdentifier(Owner owner) {
41	        return owner.getCustomerCode();
42	    }
43	
44	    /**
45	     * Renders the event as a compact JSON object with a stable key order:
46	     * {@code {"seq":..,"ownerId":..,"customerCode":..,"membershipLevel":..,"event":"OWNER_CREATED"}}.
47	     */
48	    public String toJson() {
49	        StringBuilder sb = new StringBuilder(96);
50	        sb.append('{');
51	        sb.append("\"seq\":").append(seq);
52	        sb.append(",\"ownerId\":").append(ownerId);
53	        sb.append(",\"customerCode\":").append(jsonString(customerCode));
54	        sb.append(",\"membershipLevel\":").append(membershipLevel);
55	        sb.append(",\"event\":").append(jsonString(EVENT));
56	        sb.append('}');
57	        return sb.toString();
58	    }
59	
60	    /** JSON-encodes a string value, or the literal {@code null} when absent. */
61	    private static String jsonString(String value) {
62	        if (value == null) {
63	            return "null";
64	        }
65	        StringBuilder sb = new StringBuilder(value.length() + 2);
66	        sb.append('"');
67	        for (int i = 0; i < value.length(); i++) {
68	            char c = value.charAt(i);
69	            switch (c) {
70	                case '"' -> sb.append("\\\"");
71	                case '\\' -> sb.append("\\\\");
72	                case '\n' -> sb.append("\\n");
73	                case '\r' -> sb.append("\\r");
74	                case '\t' -> sb.append("\\t");
75	                default -> {
76	                    if (c < 0x20) {
77	                        sb.append(String.format("\\u%04x", (int) c));
78	                    } else {
79	                        sb.append(c);
80	                    }
81	                }
82	            }
83	        }
84	        sb.append('"');
85	        return sb.toString();
86	    }
87	}
