3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.model.Sha256;
6	
7	/**
8	 * Assigns the owner's {@code householdId} deterministically: the first 12 hexadecimal
9	 * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}. Two
10	 * owners with the same last name and postcode therefore always derive the <em>same</em>
11	 * {@code householdId} — they are automatically the same household, with no opt-in and no
12	 * back-fill. Runs after {@link BuildOwner} (so the entity carries its stored last name and
13	 * postcode) and before {@link AssignHouseholdSize} (which counts the household).
14	 *
15	 * <p>Duplicate detection no longer keys on this value: it is now the single
16	 * {@code identityKey} (see {@link CheckOwnerIdentityUnique}). The {@code householdId}
17	 * remains a descriptive grouping used to size the household.
18	 */
19	public class AssignHousehold {
20	
21	    public void service(@Val Owner owner) {
22	        String key = normalize(owner.getLastName()) + "|" + nullToEmpty(owner.getPostcode());
23	        owner.setHouseholdId(hash12(key));
24	    }
25	
26	    /** The first 12 lower-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
27	    private static String hash12(String value) {
28	        return Sha256.hex(value).substring(0, 12);
29	    }
30	
31	    private static String nullToEmpty(String value) {
32	        return value == null ? "" : value;
33	    }
34	
35	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
36	    private static String normalize(String value) {
37	        if (value == null) {
38	            return "";
39	        }
40	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
41	    }
42	}
