package org.springframework.samples.petclinic.model;

import java.util.Map;
import java.util.regex.Pattern;

/**
 * Derives an owner's locality (region), preferring the postcode: the postcode range is
 * looked up first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only when the
 * postcode is absent or in no known range does it fall back to the fixed city-to-region
 * table. This returns the same region for known cities but disambiguates cities that
 * share a name.
 */
public final class Locality {

    /** A postcode must be exactly four digits to derive a region. */
    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");

    /** City -> canonical region. Anything not listed derives {@link #UNKNOWN}. */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    /** Returned when the region can be derived from neither postcode nor city. */
    public static final String UNKNOWN = "UNKNOWN";

    private Locality() {
    }

    /**
     * The canonical region string for the given city, or {@link #UNKNOWN} when the
     * city is null or not in the fixed city-to-region table.
     */
    public static String of(String city) {
        if (city == null) {
            return UNKNOWN;
        }
        return CITY_REGION.getOrDefault(city, UNKNOWN);
    }

    /**
     * The canonical region string derived from the postcode range first (NSW 2000-2099,
     * VIC 3000-3099, QLD 4000-4099), falling back to the city-to-region table when the
     * postcode is null, malformed, or in no known range. {@link #UNKNOWN} when neither
     * yields a region.
     */
    public static String of(String city, String postcode) {
        String byPostcode = fromPostcode(postcode);
        if (!UNKNOWN.equals(byPostcode)) {
            return byPostcode;
        }
        return of(city);
    }

    /**
     * The canonical region string derived from the postcode alone (NSW 2000-2099,
     * VIC 3000-3099, QLD 4000-4099), with no city fallback. This is the REGION segment
     * of an owner's {@code customerCode}. {@link #UNKNOWN} when the postcode is null,
     * malformed, or in no known range.
     */
    public static String regionOf(String postcode) {
        return fromPostcode(postcode);
    }

    /**
     * The owner's locality, taken from the REGION segment of its {@code customerCode}
     * (the new region-and-hash identity). When the owner has no customer code (e.g. a
     * record created before an identity was assigned) it falls back to deriving the
     * region from the owner's postcode and city.
     */
    public static String of(Owner owner) {
        String customerCode = owner.getCustomerCode();
        if (customerCode != null) {
            int dash = customerCode.indexOf('-');
            if (dash > 0) {
                return customerCode.substring(0, dash);
            }
        }
        return of(owner.getCity(), owner.getPostcode());
    }

    /** Region whose range contains the 4-digit postcode, or {@link #UNKNOWN}. */
    private static String fromPostcode(String postcode) {
        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
            return UNKNOWN;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return UNKNOWN;
    }
}

package org.springframework.samples.petclinic.model;

import java.time.LocalDate;
import java.time.Month;

/**
 * Derives an owner's fiscal year from their (business-day-adjusted) registrationDate.
 *
 * <p>The fiscal year starts on 1 July and is labelled by the calendar year in which it
 * ends: a date on or after 1 July falls in the fiscal year ending the following 30 June.
 * For example 1 July 2025 and 12 September 2025 both fall in fiscal year 2026, while 30
 * June 2025 falls in fiscal year 2025.
 *
 * <p>{@link #of(Owner)} formats this as {@code 'FY<YY>'} (the two-digit ending year, e.g.
 * {@code 'FY26'}); {@link #shortYear(LocalDate)} exposes the two-digit ending year on its
 * own and {@link #yearOf(LocalDate)} the four-digit ending year, for callers that build
 * their own segments (such as the membership number).
 */
public final class FiscalYear {

    /** The month on whose first day the fiscal year begins. */
    private static final int START_MONTH = Month.JULY.getValue();

    private FiscalYear() {
    }

    /** The fiscal year label ({@code 'FY<YY>'}) for the owner, or null when unregistered. */
    public static String of(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return null;
        }
        return "FY" + shortYear(registrationDate);
    }

    /** The two-digit ending year ({@code 'YY'}) of the fiscal year that {@code date} falls in. */
    public static String shortYear(LocalDate date) {
        return String.format("%02d", yearOf(date) % 100);
    }

    /** The fiscal year (the calendar year it ends in) that {@code date} falls in. */
    public static int yearOf(LocalDate date) {
        return date.getMonthValue() >= START_MONTH ? date.getYear() + 1 : date.getYear();
    }
}

