package org.springframework.samples.petclinic.model;

/**
 * Derives the HASH8 segment of an owner's region-and-hash identity: the first 8 upper-case
 * hexadecimal characters of the {@link Sha256} digest over the concatenation of the owner's
 * normalized (E.164) telephone and lastName (e.g. {@code 1A2B3C4D}).
 *
 * <p>This is the one place the segment is computed, so every identity that embeds it (the
 * owner's {@code customerCode} today) reads the same value rather than re-deriving it. A
 * null telephone or lastName contributes an empty string to the concatenation.
 */
public final class Hash8 {

    private Hash8() {
    }

    /** The 8-character upper-case hex HASH8 segment for the given owner. */
    public static String of(Owner owner) {
        String source = nullToEmpty(owner.getTelephone()) + nullToEmpty(owner.getLastName());
        return Sha256.hex(source).substring(0, 8).toUpperCase();
    }

    private static String nullToEmpty(String value) {
        return value == null ? "" : value;
    }
}

package org.springframework.samples.petclinic.model;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Lower-case hexadecimal SHA-256 of a string's UTF-8 bytes — the one place the digest is
 * computed for the values several derived fields hang off (an owner's {@code householdId}
 * and the HASH segment of its {@code customerCode}). Callers that want a shorter code take
 * a prefix of {@link #hex(String)} (and upper-case it where required), keeping the digest
 * itself in a single place rather than re-deriving it per field.
 */
public final class Sha256 {

    private Sha256() {
    }

    /** The full 64-character lower-case hex SHA-256 over the UTF-8 bytes of {@code value}. */
    public static String hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}

package org.springframework.samples.petclinic.model;

/**
 * Computes a single Luhn check digit (0-9) over the digits contained in a string — the one
 * place the algorithm lives, so the several places that pin a Luhn digit onto an identifier
 * (such as an owner's {@link CheckDigit}) delegate here rather than re-implementing it.
 *
 * <p>The digits are processed right-to-left, doubling every second digit starting with the
 * rightmost (subtracting 9 when a doubled digit exceeds 9); the check digit is the amount
 * needed to bring the running total to the next multiple of ten. Non-digit characters are
 * ignored.
 */
public final class Luhn {

    private Luhn() {
    }

    /** The Luhn check digit (0-9) over the digits contained in {@code source}. */
    public static int digit(String source) {
        int sum = 0;
        boolean dbl = true;
        for (int i = source.length() - 1; i >= 0; i--) {
            char c = source.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }
}

